import hskJson from '@/data/hsk.json';

/**
 * The official HSK 2012 (HSK 2.0) vocabulary, levels 1-6.
 *
 * Used to answer one question on a character page: where does this character
 * actually turn up? A mnemonic fixes a character in isolation; the words show
 * it doing work. Regenerated by scripts/fetch-hsk.mjs, never at build time.
 */
export interface HskWord {
  word: string;
  pinyin: string;
  gloss: string;
  /** 1-6. A word listed at two levels is filed at the lower one. */
  level: number;
}

// Same widening problem as lib/data.ts: the JSON import infers a union of
// literal types. Shape is validated by scripts/check-data.mjs.
export const hskWords = hskJson as unknown as HskWord[];

const byChar = new Map<string, HskWord[]>();
for (const entry of hskWords) {
  // A word like 爸爸 contains 爸 once for this purpose, not twice.
  for (const char of new Set(entry.word)) {
    const bucket = byChar.get(char);
    if (bucket) bucket.push(entry);
    else byChar.set(char, [entry]);
  }
}

export interface HskLevelGroup {
  level: number;
  words: HskWord[];
}

/**
 * Every HSK word containing the character, split by level and in the order the
 * official list gives them. Empty for the 357 characters the syllabus never
 * uses. Single-character words are included: that a character is itself HSK 1
 * vocabulary is worth seeing.
 */
export function hskForChar(char: string): HskLevelGroup[] {
  const words = byChar.get(char);
  if (!words) return [];

  const byLevel = new Map<number, HskWord[]>();
  for (const word of words) {
    const bucket = byLevel.get(word.level);
    if (bucket) bucket.push(word);
    else byLevel.set(word.level, [word]);
  }

  return [...byLevel.entries()]
    .map(([level, group]) => ({ level, words: group }))
    .sort((a, b) => a.level - b.level);
}
